"""Matrix multiplication of two lower-triangular matrices followed by lower-triangular masking."""

import jax
import jax.numpy as jnp

CONFIG = {
    'name': '15_Matmul_for_lower_triangular_matrices',
    'M': 4096,
}


def create_inputs(dtype=jnp.float32):
    m = CONFIG['M']
    k1, k2 = jax.random.split(jax.random.key(0), 2)
    a = jnp.tril(jax.random.uniform(k1, (m, m), dtype=dtype))
    b = jnp.tril(jax.random.uniform(k2, (m, m), dtype=dtype))
    return (a, b)


def workload(a, b):
    return jnp.tril(jnp.matmul(a, b))

"""Matrix-vector multiplication (C = A @ B)."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': '4_Matrix_vector_multiplication_',
    'M': 2048,
    'K': 65536,
}

def create_inputs(dtype=jnp.float32):
    k1, k2 = jax.random.split(jax.random.key(0), 2)
    M, K = CONFIG['M'], CONFIG['K']
    A = jax.random.uniform(k1, (M, K), dtype=dtype)
    B = jax.random.uniform(k2, (K, 1), dtype=dtype)
    return (A, B)

def workload(A, B):
    return jnp.matmul(A, B)

"""3D tensor-matrix multiplication (matmul)."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': '10_3D_tensor_matrix_multiplication',
    'N': 32,
    'M': 1024,
    'K': 2048,
    'L': 768,
}


def create_inputs(dtype=jnp.float32):
    k1, k2 = jax.random.split(jax.random.key(0), 2)
    n, m, k, l = CONFIG['N'], CONFIG['M'], CONFIG['K'], CONFIG['L']
    a = jax.random.uniform(k1, (n, m, k), dtype=dtype)
    b = jax.random.uniform(k2, (k, l), dtype=dtype)
    return (a, b)


def workload(a, b):
    return jnp.matmul(a, b)
